using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renames the discriminator property
        // from "Discriminator" to "$type". Existing documents still use
        // "Discriminator", so we must preserve the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 changes the id format from
        // "EntityType|Key" (e.g. "Blog|1") to just the raw key value.
        // Existing documents use the old format, so we preserve it.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id")
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>()
            .UseETagConcurrency();

        // Breaking change 3: HasIndex() on a Cosmos entity now throws at
        // model building time instead of being silently ignored.
        // REMOVED: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
        // Cosmos DB indexes are managed via indexing policy, not EF.
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

